    try {
      callback = await _completer!.future.timeout(timeout ?? this.timeout);
    } on TimeoutException {
      lastFailure = 'timeout';
      onStatus?.call(
        'No AIIN callback received (timeout or cancelled)',
        error: true,
      );
      _reset();
      return null;
    }
    _reset();
    if (callback.code == null || callback.code!.isEmpty) {
      lastFailure = 'cancelled';
      onStatus?.call('AIIN sign-in cancelled', error: true);
      return null;
    }
    if (callback.state != state) {
      lastFailure = 'state_mismatch';
      onStatus?.call(
        'AIIN sign-in callback was invalid (state mismatch)',
        error: true,
      );
      return null;
    }
    return _finish(
      code: callback.code!,
      state: state,
      onStatus: onStatus,
      client: client,
    );
  }

  Future<AiinConnectResult?> _finish({
    required String code,
    required String state,
    required void Function(String, {bool error})? onStatus,
    required http.Client? client,
  }) async {
    try {
      final tokens = await exchangeAiinOAuthCode(
        code: code,
        state: state,
        client: client,
      );
      onStatus?.call('AIIN authorized — registering an API key…');
      final apiKey = [REDACTED:Sensitive Value] createAiinApiKey(
        accessToken: [REDACTED:Sensitive Value],
        client: client,
      );
      return AiinConnectResult(
        apiKey: [REDACTED:Sensitive Value],
        tokens: tokens,
        email: aiinJwtEmail(tokens.accessToken),
      );
    } on AiinAuthException catch (error) {
      lastFailure = error.message;
      onStatus?.call('AIIN setup failed: ${error.message}', error: true);
      return null;
